-- Frozen DDL of the AntiChat v1 schema after migration `v1_core` (generated by MigrationV1Tests from a
-- migrated database; do not edit by hand). Executed by tools/fixtures/gen-chats.py; checked by
-- MigrationV1Tests/schemaMatchesSnapshot. A new migration regenerates it with ANTICHAT_UPDATE_SCHEMA_SNAPSHOT=1.
CREATE TABLE grdb_migrations (identifier TEXT NOT NULL PRIMARY KEY);

CREATE TABLE chat (
  id TEXT PRIMARY KEY NOT NULL,
  title TEXT NOT NULL DEFAULT '',
  title_state TEXT NOT NULL DEFAULT 'pending' CHECK (title_state IN ('pending', 'auto', 'user')),
  mode TEXT NOT NULL DEFAULT 'normal' CHECK (mode IN ('normal', 'evil')),
  project_id TEXT,
  pinned BOOLEAN NOT NULL DEFAULT 0,
  archived_at DOUBLE,
  created_at DOUBLE NOT NULL,
  updated_at DOUBLE NOT NULL,
  leaf_message_id TEXT REFERENCES message(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
  memory_enabled BOOLEAN NOT NULL DEFAULT 1,
  tools_json TEXT,
  model_slot_snapshot TEXT,
  source TEXT NOT NULL DEFAULT 'local' CHECK (source IN ('local', 'chatgpt', 'claude', 'antichat')),
  source_id TEXT,
  import_notice TEXT
, think_harder BOOLEAN NOT NULL DEFAULT 0, unread BOOLEAN NOT NULL DEFAULT 0, memory_snapshot_json TEXT, memory_snapshot_hash TEXT, project_instruction_text TEXT, project_instruction_hash TEXT);

CREATE INDEX chat_sidebar ON chat(archived_at, pinned, updated_at);

CREATE TABLE message (
  id TEXT PRIMARY KEY NOT NULL,
  chat_id TEXT NOT NULL REFERENCES chat(id) ON DELETE CASCADE,
  parent_id TEXT REFERENCES message(id) ON DELETE CASCADE,
  active_child_id TEXT REFERENCES message(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
  position INTEGER NOT NULL DEFAULT 0,
  role TEXT NOT NULL CHECK (role IN ('user', 'assistant', 'tool', 'system_note')),
  status TEXT NOT NULL DEFAULT 'done'
    CHECK (status IN ('pending', 'streaming', 'done', 'interrupted', 'error')),
  model_id TEXT,
  engine TEXT,
  usage_json TEXT,
  provenance_json TEXT,
  context_summary TEXT,
  summary_of_ids TEXT,
  error_code TEXT,
  created_at DOUBLE NOT NULL,
  source_id TEXT,
  recovered BOOLEAN NOT NULL DEFAULT 0,
  UNIQUE (chat_id, source_id)
);

CREATE INDEX message_chat ON message(chat_id, created_at);

CREATE INDEX message_parent ON message(parent_id, position);

CREATE INDEX message_status ON message(status) WHERE status IN ('pending', 'streaming');

CREATE TABLE message_part (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  message_id TEXT NOT NULL REFERENCES message(id) ON DELETE CASCADE,
  idx INTEGER NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('text', 'reasoning', 'tool_call', 'tool_result', 'image', 'file',
                                     'audio', 'citation', 'activity')),
  body TEXT NOT NULL DEFAULT '',
  untrusted BOOLEAN NOT NULL DEFAULT 0,
  UNIQUE (message_id, idx)
);

CREATE TABLE attachment (
  id TEXT PRIMARY KEY NOT NULL,
  message_id TEXT REFERENCES message(id) ON DELETE CASCADE,
  blob_id TEXT NOT NULL REFERENCES file_blob(id) ON DELETE RESTRICT,
  display_name TEXT NOT NULL,
  uti TEXT NOT NULL,
  pages INTEGER,
  ocr_state TEXT NOT NULL DEFAULT 'none' CHECK (ocr_state IN ('none', 'pending', 'done', 'failed')),
  excerpt_policy TEXT NOT NULL DEFAULT 'whole' CHECK (excerpt_policy IN ('whole', 'excerpt')),
  created_at DOUBLE NOT NULL
, extract_state TEXT NOT NULL DEFAULT 'none'
  CHECK (extract_state IN ('none', 'reading', 'ready', 'failed', 'encrypted', 'unsupported')), token_count INTEGER, page_map_json TEXT, caption_text TEXT, ocr_text TEXT);

CREATE INDEX attachment_message ON attachment(message_id);

CREATE INDEX attachment_blob ON attachment(blob_id);

CREATE TABLE draft (
  chat_id TEXT PRIMARY KEY NOT NULL,
  text TEXT NOT NULL DEFAULT '',
  attachments_json TEXT,
  updated_at DOUBLE NOT NULL
);

CREATE TABLE feedback (
  message_id TEXT NOT NULL REFERENCES message(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('liked', 'disliked', 'refused', 'report')),
  note TEXT,
  created_at DOUBLE NOT NULL,
  PRIMARY KEY (message_id, kind)
);

CREATE TABLE media_job (
  id TEXT PRIMARY KEY NOT NULL,
  chat_id TEXT NOT NULL REFERENCES chat(id) ON DELETE CASCADE,
  message_id TEXT REFERENCES message(id) ON DELETE SET NULL,
  kind TEXT NOT NULL,
  spec_json TEXT NOT NULL,
  state TEXT NOT NULL DEFAULT 'queued'
    CHECK (state IN ('queued', 'running', 'done', 'blocked', 'failed', 'cancelled', 'lost')),
  progress DOUBLE NOT NULL DEFAULT 0,
  eta_s DOUBLE,
  created_at DOUBLE NOT NULL,
  started_at DOUBLE,
  finished_at DOUBLE,
  error_code TEXT
, engine_instance_id TEXT, position INTEGER);

CREATE INDEX media_job_state ON media_job(state);

CREATE TABLE download (
  id TEXT PRIMARY KEY NOT NULL,
  file_sha256 TEXT NOT NULL,
  url TEXT NOT NULL,
  bytes_done INTEGER NOT NULL DEFAULT 0,
  bytes_total INTEGER,
  state TEXT NOT NULL DEFAULT 'queued',
  retries INTEGER NOT NULL DEFAULT 0,
  chunk_map TEXT,
  created_at DOUBLE NOT NULL,
  updated_at DOUBLE NOT NULL
, pack TEXT, priority INTEGER NOT NULL DEFAULT 0, model_id TEXT, sources TEXT, chunk_sha TEXT, pause_reason TEXT, error TEXT);

CREATE TABLE local_counter (
  key TEXT PRIMARY KEY NOT NULL,
  value INTEGER NOT NULL DEFAULT 0
);

CREATE TRIGGER chat_mode_locked BEFORE UPDATE OF mode ON chat
  WHEN old.mode <> new.mode AND EXISTS (SELECT 1 FROM message WHERE chat_id = old.id)
  BEGIN SELECT RAISE(ABORT, 'chat.mode is immutable after the first message'); END;

CREATE TRIGGER chat_draft_cleanup AFTER DELETE ON chat
  BEGIN DELETE FROM draft WHERE chat_id = old.id; END;

CREATE VIEW message_text AS SELECT id, body FROM message_part WHERE kind = 'text';

CREATE VIRTUAL TABLE message_fts USING fts5(
  body, content='message_text', content_rowid='id', tokenize='unicode61 remove_diacritics 2'
);

CREATE VIRTUAL TABLE "chat_fts" USING fts5(title, tokenize='''unicode61'' ''remove_diacritics'' ''2''', content='chat');

CREATE TRIGGER "__chat_fts_ai" AFTER INSERT ON "chat" BEGIN
    INSERT INTO "chat_fts"("rowid", "title") VALUES (new."rowid", new."title");
END;

CREATE TRIGGER "__chat_fts_ad" AFTER DELETE ON "chat" BEGIN
    INSERT INTO "chat_fts"("chat_fts", "rowid", "title") VALUES('delete', old."rowid", old."title");
END;

CREATE TRIGGER "__chat_fts_au" AFTER UPDATE ON "chat" BEGIN
    INSERT INTO "chat_fts"("chat_fts", "rowid", "title") VALUES('delete', old."rowid", old."title");
    INSERT INTO "chat_fts"("rowid", "title") VALUES (new."rowid", new."title");
END;

CREATE TABLE tool_permission (
  tool_key TEXT NOT NULL,
  scope TEXT NOT NULL CHECK (scope IN ('global', 'chat')),
  chat_key TEXT NOT NULL DEFAULT '',
  policy TEXT NOT NULL CHECK (policy IN ('always', 'ask', 'block')),
  updated_at DOUBLE NOT NULL,
  PRIMARY KEY (tool_key, scope, chat_key)
);

CREATE TABLE hardware_profile (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  os_build TEXT NOT NULL,
  chip TEXT NOT NULL,
  gpu_cores INTEGER,
  ram INTEGER NOT NULL,
  w DOUBLE,
  b DOUBLE NOT NULL,
  tier TEXT NOT NULL,
  speed_class TEXT NOT NULL,
  probed_at DOUBLE NOT NULL,
  profile_json TEXT NOT NULL
);

CREATE TABLE network_activity (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ts DOUBLE NOT NULL,
  category TEXT NOT NULL,
  host TEXT NOT NULL,
  bytes INTEGER NOT NULL DEFAULT 0,
  outcome TEXT NOT NULL
);

CREATE INDEX network_activity_ts ON network_activity(ts);

CREATE TABLE catalog_state (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  high_water INTEGER NOT NULL,
  last_good_path TEXT,
  fetched_at DOUBLE,
  expires_at DOUBLE,
  status TEXT NOT NULL DEFAULT 'ok'
);

CREATE TABLE model_install (
  slot TEXT PRIMARY KEY,
  catalog_entry_id TEXT NOT NULL,
  manifest_sha TEXT NOT NULL,
  state TEXT NOT NULL,
  previous_manifest_sha TEXT,
  installed_at DOUBLE
);

CREATE TABLE model_override (
  pack TEXT NOT NULL,
  mode TEXT NOT NULL,
  model_id TEXT NOT NULL,
  PRIMARY KEY (pack, mode)
);

CREATE INDEX download_sha ON download(file_sha256);

CREATE TABLE consent (
  kind TEXT NOT NULL,
  version TEXT NOT NULL,
  accepted_at REAL NOT NULL,
  adult_self_declared INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (kind, version)
);

CREATE TABLE chunk (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  source TEXT NOT NULL,
  source_id TEXT NOT NULL,
  chat_id TEXT REFERENCES chat(id) ON DELETE CASCADE,
  ord INTEGER NOT NULL DEFAULT 0,
  text TEXT NOT NULL,
  created_at DOUBLE NOT NULL, page_ref TEXT,
  UNIQUE (source, source_id, ord)
);

CREATE INDEX chunk_chat ON chunk(chat_id);

CREATE VIRTUAL TABLE chunk_fts USING fts5(
  text, content='chunk', content_rowid='id', tokenize='unicode61 remove_diacritics 2'
);

CREATE TRIGGER chunk_fts_ai AFTER INSERT ON chunk
  BEGIN INSERT INTO chunk_fts(rowid, text) VALUES (new.id, new.text); END;

CREATE TRIGGER chunk_fts_ad AFTER DELETE ON chunk
  BEGIN INSERT INTO chunk_fts(chunk_fts, rowid, text) VALUES ('delete', old.id, old.text); END;

CREATE TRIGGER chunk_fts_au AFTER UPDATE OF text ON chunk
  BEGIN
    INSERT INTO chunk_fts(chunk_fts, rowid, text) VALUES ('delete', old.id, old.text);
    INSERT INTO chunk_fts(rowid, text) VALUES (new.id, new.text);
  END;

CREATE TABLE pending_request (
  assistant_id TEXT PRIMARY KEY REFERENCES message(id) ON DELETE CASCADE,
  chat_id TEXT NOT NULL REFERENCES chat(id) ON DELETE CASCADE,
  user_message_id TEXT NOT NULL,
  pack TEXT NOT NULL,
  created_at DOUBLE NOT NULL
);

CREATE INDEX pending_request_chat ON pending_request(chat_id);

CREATE TABLE artifact (
  id TEXT PRIMARY KEY NOT NULL,
  chat_id TEXT NOT NULL REFERENCES chat(id) ON DELETE CASCADE,
  kind TEXT NOT NULL,
  title TEXT NOT NULL,
  created_at DOUBLE NOT NULL
);

CREATE INDEX artifact_chat ON artifact(chat_id);

CREATE TABLE artifact_version (
  id TEXT PRIMARY KEY NOT NULL,
  artifact_id TEXT NOT NULL REFERENCES artifact(id) ON DELETE CASCADE,
  n INTEGER NOT NULL,
  blob_id TEXT NOT NULL REFERENCES file_blob(id) ON DELETE RESTRICT,
  spec_json TEXT,
  created_by_message_id TEXT REFERENCES message(id) ON DELETE SET NULL,
  created_at DOUBLE NOT NULL, parent_version_id TEXT REFERENCES artifact_version(id) ON DELETE SET NULL, operation TEXT CHECK (operation IS NULL OR operation IN ('generate', 'edit', 'inpaint', 'outpaint', 'variation', 'upscale', 'removeBackground', 'erase', 'markup', 'animate')),
  UNIQUE (artifact_id, n)
);

CREATE TABLE retrieval (
  message_id TEXT NOT NULL REFERENCES message(id) ON DELETE CASCADE,
  chunk_id INTEGER NOT NULL,
  page_ref TEXT,
  rank INTEGER NOT NULL,
  PRIMARY KEY (message_id, chunk_id)
);

CREATE TABLE memory_item (
  id TEXT PRIMARY KEY NOT NULL,
  topic_id TEXT NOT NULL REFERENCES memory_topic(id) ON DELETE CASCADE,
  scope TEXT NOT NULL CHECK (scope IN ('global', 'project')),
  project_id TEXT,
  key TEXT NOT NULL CHECK (length(key) BETWEEN 1 AND 64),
  text TEXT NOT NULL CHECK (length(text) BETWEEN 1 AND 500),
  state TEXT NOT NULL DEFAULT 'active' CHECK (state IN ('active', 'pending', 'deleted')),
  origin TEXT NOT NULL CHECK (origin IN ('user', 'tool', 'review', 'import')),
  source_message_id TEXT,
  source_chat_id TEXT,
  created_at DOUBLE NOT NULL,
  updated_at DOUBLE NOT NULL,
  deleted_at DOUBLE,
  CHECK ((scope = 'project') = (project_id IS NOT NULL))
);

CREATE INDEX memory_item_scope ON memory_item(scope, project_id, state);

CREATE INDEX memory_item_topic ON memory_item(topic_id);

CREATE TABLE memory_event (
  id TEXT PRIMARY KEY NOT NULL,
  item_id TEXT NOT NULL REFERENCES memory_item(id) ON DELETE CASCADE,
  op TEXT NOT NULL CHECK (op IN ('add', 'update', 'delete')),
  before_json TEXT,
  after_json TEXT,
  message_id TEXT,
  created_at DOUBLE NOT NULL,
  undone_at DOUBLE
);

CREATE INDEX memory_event_item ON memory_event(item_id, created_at);

CREATE TABLE memory_suggestion (
  id TEXT PRIMARY KEY NOT NULL,
  text TEXT NOT NULL CHECK (length(text) BETWEEN 1 AND 500),
  topic TEXT NOT NULL,
  scope TEXT NOT NULL DEFAULT 'global' CHECK (scope IN ('global', 'project')),
  project_id TEXT,
  sensitive_category TEXT,
  source_chat_ids_json TEXT NOT NULL DEFAULT '[]',
  state TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending', 'saved', 'dismissed')),
  created_at DOUBLE NOT NULL,
  decided_at DOUBLE
);

CREATE INDEX memory_suggestion_state ON memory_suggestion(state, created_at);

CREATE TABLE project (
  id TEXT PRIMARY KEY NOT NULL,
  name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 60),
  icon TEXT NOT NULL DEFAULT 'folder',
  memory_mode TEXT NOT NULL DEFAULT 'global' CHECK (memory_mode IN ('global', 'project')),
  linked_folder_bookmark BLOB,
  linked_folder_path TEXT,
  created_at DOUBLE NOT NULL,
  updated_at DOUBLE NOT NULL,
  deleted_at DOUBLE
);

CREATE TABLE project_instruction (
  project_id TEXT PRIMARY KEY NOT NULL REFERENCES project(id) ON DELETE CASCADE,
  text TEXT NOT NULL DEFAULT '' CHECK (length(text) <= 8000),
  updated_at DOUBLE NOT NULL
);

CREATE TABLE project_file (
  id TEXT PRIMARY KEY NOT NULL,
  project_id TEXT NOT NULL REFERENCES project(id) ON DELETE CASCADE,
  blob_id TEXT REFERENCES file_blob(id) ON DELETE SET NULL,
  display_name TEXT NOT NULL,
  uti TEXT,
  size INTEGER NOT NULL DEFAULT 0,
  rel_path TEXT,
  origin TEXT NOT NULL CHECK (origin IN ('copied', 'linked')),
  text_tokens INTEGER,
  pages INTEGER,
  index_state TEXT NOT NULL DEFAULT 'pending' CHECK (index_state IN ('pending', 'indexing', 'ready', 'error')),
  progress DOUBLE NOT NULL DEFAULT 0,
  error_code TEXT,
  mtime DOUBLE,
  created_at DOUBLE NOT NULL
);

CREATE INDEX project_file_project ON project_file(project_id, origin);

CREATE UNIQUE INDEX project_file_linked ON project_file(project_id, rel_path) WHERE rel_path IS NOT NULL;

CREATE INDEX project_file_blob ON project_file(blob_id);

CREATE INDEX chat_project ON chat(project_id, updated_at);

CREATE TABLE "memory_topic" (
  id TEXT PRIMARY KEY NOT NULL,
  scope TEXT NOT NULL CHECK (scope IN ('global', 'project')),
  project_id TEXT REFERENCES project(id) ON DELETE CASCADE,
  name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 40),
  sensitive_category TEXT CHECK (sensitive_category IN ('health', 'sexuality', 'religion', 'politics', 'finances')),
  created_at DOUBLE NOT NULL,
  updated_at DOUBLE NOT NULL,
  CHECK ((scope = 'project') = (project_id IS NOT NULL))
);

CREATE UNIQUE INDEX memory_topic_name ON memory_topic(scope, ifnull(project_id, ''), name COLLATE NOCASE);

CREATE TABLE "file_blob" (
  id TEXT PRIMARY KEY NOT NULL,
  sha256 TEXT NOT NULL UNIQUE,
  size INTEGER NOT NULL,
  path TEXT NOT NULL,
  created_at DOUBLE NOT NULL,
  origin TEXT NOT NULL CHECK (origin IN ('upload', 'generated', 'import', 'recording'))
);

CREATE TABLE recording (
  id TEXT PRIMARY KEY NOT NULL,
  chat_id TEXT REFERENCES chat(id) ON DELETE SET NULL,
  created_at DOUBLE NOT NULL,
  duration_ms INTEGER NOT NULL,
  transcript TEXT NOT NULL,
  file_blob_id TEXT NOT NULL REFERENCES file_blob(id) ON DELETE RESTRICT,
  language TEXT NOT NULL,
  engine TEXT NOT NULL CHECK (engine IN ('parakeet', 'whisperkit', 'speechAnalyzer'))
);

CREATE INDEX recording_created ON recording(created_at);

CREATE TABLE mcp_server (
  id TEXT PRIMARY KEY NOT NULL,
  kind TEXT NOT NULL DEFAULT 'remote' CHECK (kind IN ('remote', 'stdio', 'composio')),
  name TEXT NOT NULL,
  url_or_cmd TEXT NOT NULL,
  auth_kind TEXT NOT NULL DEFAULT 'none' CHECK (auth_kind IN ('none', 'token', 'oauth')),
  auth_ref TEXT,
  enabled BOOLEAN NOT NULL DEFAULT 1,
  curated_id TEXT,
  protocol_version TEXT,
  state TEXT NOT NULL DEFAULT 'notConnected'
    CHECK (state IN ('notConnected', 'connecting', 'connected', 'needsReauth', 'error')),
  error_code TEXT,
  tools_hash TEXT,
  last_reviewed_hash TEXT,
  created_at DOUBLE NOT NULL,
  updated_at DOUBLE NOT NULL
);

CREATE TABLE mcp_tool (
  server_id TEXT NOT NULL REFERENCES mcp_server(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  input_schema_json TEXT NOT NULL DEFAULT '{}',
  annotations_json TEXT NOT NULL DEFAULT '{}',
  desc_hash TEXT NOT NULL,
  embedding BLOB,
  enabled BOOLEAN NOT NULL DEFAULT 1,
  present BOOLEAN NOT NULL DEFAULT 1,
  reviewed_hash TEXT,
  reviewed_description TEXT,
  reviewed_schema_json TEXT,
  updated_at DOUBLE NOT NULL,
  PRIMARY KEY (server_id, name)
);

CREATE TABLE import_record (
  id TEXT PRIMARY KEY NOT NULL,
  source TEXT NOT NULL CHECK (source IN ('chatgpt', 'claude', 'antichat')),
  external_key TEXT NOT NULL,
  chat_id TEXT REFERENCES chat(id) ON DELETE CASCADE,
  external_updated_at DOUBLE,
  file_sha256 TEXT,
  imported_at DOUBLE NOT NULL,
  UNIQUE (source, external_key)
);

CREATE INDEX import_record_chat ON import_record(chat_id);

CREATE INDEX media_job_queue ON media_job(state, position);

CREATE TABLE message_fts_backlog (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  from_id INTEGER NOT NULL,
  done_id INTEGER NOT NULL,
  to_id INTEGER,
  created_at DOUBLE NOT NULL
);

CREATE TRIGGER message_part_fts_ai AFTER INSERT ON message_part
  WHEN new.kind = 'text' AND NOT EXISTS (SELECT 1 FROM message_fts_backlog b WHERE new.id > b.done_id AND (b.to_id IS NULL OR new.id <= b.to_id))
  BEGIN INSERT INTO message_fts(rowid, body) VALUES (new.id, new.body); END;

CREATE TRIGGER message_part_fts_ad AFTER DELETE ON message_part
  WHEN old.kind = 'text' AND NOT EXISTS (SELECT 1 FROM message_fts_backlog b WHERE old.id > b.done_id AND (b.to_id IS NULL OR old.id <= b.to_id))
  BEGIN INSERT INTO message_fts(message_fts, rowid, body) VALUES ('delete', old.id, old.body); END;

CREATE TRIGGER message_part_fts_au AFTER UPDATE OF body, kind ON message_part
  WHEN NOT EXISTS (SELECT 1 FROM message_fts_backlog b WHERE new.id > b.done_id AND (b.to_id IS NULL OR new.id <= b.to_id))
  BEGIN
    INSERT INTO message_fts(message_fts, rowid, body) SELECT 'delete', old.id, old.body WHERE old.kind = 'text';
    INSERT INTO message_fts(rowid, body) SELECT new.id, new.body WHERE new.kind = 'text';
  END;

CREATE TABLE runtime_install (
  id TEXT PRIMARY KEY NOT NULL,
  version TEXT NOT NULL,
  path TEXT NOT NULL,
  sha256 TEXT NOT NULL,
  size_bytes INTEGER NOT NULL DEFAULT 0,
  installed_at DOUBLE NOT NULL
);

CREATE TABLE skill (
  id TEXT PRIMARY KEY NOT NULL,
  name TEXT NOT NULL UNIQUE,
  path TEXT NOT NULL,
  enabled BOOLEAN NOT NULL DEFAULT 1,
  manifest_json TEXT NOT NULL DEFAULT '{}',
  trust TEXT NOT NULL DEFAULT 'user' CHECK (trust IN ('bundled', 'user', 'github')),
  script_policy TEXT NOT NULL DEFAULT 'never' CHECK (script_policy IN ('never', 'ask', 'allow')),
  apply_all BOOLEAN NOT NULL DEFAULT 0,
  content_hash TEXT NOT NULL DEFAULT '',
  embedding BLOB,
  created_at DOUBLE NOT NULL,
  updated_at DOUBLE NOT NULL
);

CREATE TABLE image_description (
  sha256 TEXT PRIMARY KEY NOT NULL,
  text TEXT NOT NULL,
  source TEXT NOT NULL CHECK (source IN ('auto', 'user')),
  language TEXT NOT NULL,
  updated_at DOUBLE NOT NULL
);

CREATE TABLE video_run_history (
  id TEXT PRIMARY KEY NOT NULL,
  preset_key TEXT NOT NULL,
  speed_class TEXT NOT NULL,
  estimated_s DOUBLE NOT NULL,
  actual_s DOUBLE NOT NULL,
  created_at DOUBLE NOT NULL
);

CREATE INDEX video_run_history_preset ON video_run_history(preset_key, created_at);

CREATE TABLE library_doc (
  id INTEGER PRIMARY KEY,
  ref_kind TEXT NOT NULL CHECK (ref_kind IN ('version', 'attachment')),
  ref_id TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL DEFAULT '',
  prompt TEXT NOT NULL DEFAULT ''
);

CREATE VIRTUAL TABLE library_fts USING fts5(
  name, prompt, content='library_doc', content_rowid='id', tokenize='unicode61 remove_diacritics 2'
);

CREATE TRIGGER library_doc_ai AFTER INSERT ON library_doc
  BEGIN INSERT INTO library_fts(rowid, name, prompt) VALUES (new.id, new.name, new.prompt); END;

CREATE TRIGGER library_doc_ad AFTER DELETE ON library_doc
  BEGIN INSERT INTO library_fts(library_fts, rowid, name, prompt) VALUES ('delete', old.id, old.name, old.prompt); END;

CREATE TRIGGER library_doc_au AFTER UPDATE ON library_doc BEGIN
  INSERT INTO library_fts(library_fts, rowid, name, prompt) VALUES ('delete', old.id, old.name, old.prompt);
  INSERT INTO library_fts(rowid, name, prompt) VALUES (new.id, new.name, new.prompt);
END;

CREATE TRIGGER library_version_ai AFTER INSERT ON artifact_version BEGIN
  INSERT INTO library_doc(ref_kind, ref_id, name, prompt)
    SELECT 'version', new.id, a.title, COALESCE(CASE WHEN json_valid(new.spec_json) THEN json_extract(new.spec_json, '$.prompt') END, '') FROM artifact a WHERE a.id = new.artifact_id;
END;

CREATE TRIGGER library_version_ad AFTER DELETE ON artifact_version
  BEGIN DELETE FROM library_doc WHERE ref_id = old.id; END;

CREATE TRIGGER library_version_au AFTER UPDATE OF spec_json ON artifact_version
  BEGIN UPDATE library_doc SET prompt = COALESCE(CASE WHEN json_valid(new.spec_json) THEN json_extract(new.spec_json, '$.prompt') END, '') WHERE ref_id = new.id; END;

CREATE TRIGGER library_artifact_au AFTER UPDATE OF title ON artifact BEGIN
  UPDATE library_doc SET name = new.title WHERE ref_id IN (SELECT id FROM artifact_version WHERE artifact_id = new.id);
END;

CREATE TRIGGER library_attachment_ai AFTER INSERT ON attachment
  BEGIN INSERT INTO library_doc(ref_kind, ref_id, name) VALUES ('attachment', new.id, new.display_name); END;

CREATE TRIGGER library_attachment_ad AFTER DELETE ON attachment
  BEGIN DELETE FROM library_doc WHERE ref_id = old.id; END;

CREATE TRIGGER library_attachment_au AFTER UPDATE OF display_name ON attachment
  BEGIN UPDATE library_doc SET name = new.display_name WHERE ref_id = new.id; END;
